CREATE OR REPLACE FUNCTION public.apply_daily_trust_penalties(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    d date;
    first_day date;
    last_day date;
    loan_id uuid;
    before_limit integer;
    after_limit integer;

BEGIN

    PERFORM 1
    FROM public.profiles
    WHERE id = p_user_id
    FOR UPDATE;


    INSERT INTO public.kash_trust_state(
        user_id,
        cycle_peak,
        clean_cycle
    )
    SELECT
        id,
        trust_score,
        trust_score = 0
    FROM public.profiles
    WHERE id = p_user_id
    ON CONFLICT DO NOTHING;


    SELECT greatest(
        min(
            (l.due_date AT TIME ZONE 'Africa/Nairobi')::date + 1
        ),
        (
            s.policy_started_at
            AT TIME ZONE 'Africa/Nairobi'
        )::date
    )
    INTO first_day

    FROM public.loans l

    CROSS JOIN public.kash_trust_state s

    WHERE l.borrower_id = p_user_id
      AND s.user_id = p_user_id
      AND l.status NOT IN (
          'REPAID',
          'RECOVERED_EXTERNALLY'
      )
      AND l.due_date < now()

    GROUP BY s.policy_started_at;


    last_day :=
        (
            now()
            AT TIME ZONE 'Africa/Nairobi'
        )::date;


    IF first_day IS NULL
       OR first_day > last_day
    THEN
        RETURN;
    END IF;


    first_day :=
        greatest(
            first_day,
            (
                SELECT max(penalty_date) + 1
                FROM public.kash_trust_daily_penalties
                WHERE user_id = p_user_id
            )
        );


    IF first_day > last_day THEN
        RETURN;
    END IF;


    FOR d IN

        SELECT generate_series(
            first_day::timestamp,
            last_day::timestamp,
            interval '1 day'
        )::date

    LOOP

        SELECT id
        INTO loan_id

        FROM public.loans

        WHERE borrower_id = p_user_id
          AND status NOT IN (
              'REPAID',
              'RECOVERED_EXTERNALLY'
          )
          AND (
              due_date
              AT TIME ZONE 'Africa/Nairobi'
          )::date < d

        ORDER BY due_date, id
        LIMIT 1;


        IF loan_id IS NULL THEN
            CONTINUE;
        END IF;


        SELECT borrowing_limit
        INTO before_limit

        FROM public.profiles
        WHERE id = p_user_id;


        INSERT INTO public.kash_trust_daily_penalties(
            user_id,
            penalty_date,
            related_loan_id,
            limit_before,
            limit_after
        )
        VALUES(
            p_user_id,
            d,
            loan_id,
            before_limit,
            before_limit
        )
        ON CONFLICT DO NOTHING;


        IF NOT FOUND THEN
            CONTINUE;
        END IF;


        PERFORM public.record_trust_event(
            p_user_id,
            'DAILY_DELAY',
            -10,

            format(
                'Payment delayed on %s; daily limit reduction approximately 0.288194%%.',
                d
            ),

            loan_id
        );


        SELECT borrowing_limit
        INTO after_limit

        FROM public.profiles
        WHERE id = p_user_id;


        UPDATE public.kash_trust_daily_penalties

        SET limit_after = after_limit

        WHERE user_id = p_user_id
          AND penalty_date = d;

    END LOOP;

END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_loan_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
    v_request public.loan_requests%rowtype;
begin
    if auth.uid() is null then
        raise exception 'Authentication required';
    end if;

    select *
    into v_request
    from public.loan_requests
    where id = p_request_id;

    if not found then
        raise exception 'Loan request not found';
    end if;

    if v_request.borrower_id <> auth.uid() then
        raise exception 'You can only cancel your own loan request';
    end if;

    -- Cannot cancel once funding has started.
    if coalesce(v_request.funded_amount, 0) > 0 then
        raise exception 'A funded request cannot be cancelled';
    end if;

    if exists (
        select 1
        from public.loan_offers
        where loan_request_id = p_request_id
    ) then
        raise exception 'A request with an offer cannot be cancelled';
    end if;

    -- Restore the amount reserved when this request was created.
    update public.profiles
    set available_limit = least(
        borrowing_limit,
        available_limit + v_request.requested_amount
    )
    where id = auth.uid();

    -- Remove the request.
    delete from public.loan_requests
    where id = p_request_id
      and borrower_id = auth.uid();

    if not found then
        raise exception 'Loan request could not be cancelled';
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_member_profile(p_email text, p_full_name text, p_username text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid;
    v_profile public.profiles;
begin
    -- The logged-in Supabase Auth user
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception 'Not authenticated';
    end if;

    -- Basic validation
    if nullif(trim(p_full_name), '') is null then
        raise exception 'Full name is required';
    end if;

    if nullif(trim(p_username), '') is null then
        raise exception 'Username is required';
    end if;

    -- Update the existing profile.
    update public.profiles
    set
        full_name = trim(p_full_name),
        username = trim(p_username)
    where id = v_user_id
    returning * into v_profile;

    -- If no profile exists yet, create it using your table defaults.
    if not found then
        insert into public.profiles (
            id,
            full_name,
            username
        )
        values (
            v_user_id,
            trim(p_full_name),
            trim(p_username)
        )
        returning * into v_profile;
    end if;

    return v_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_loan_request(p_amount integer, p_purpose text, p_description text, p_period_days integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_request_id uuid;
    v_available_limit integer;
    v_frozen boolean;
    v_status text;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be greater than zero';
    END IF;

    IF p_purpose IS NULL OR btrim(p_purpose) = '' THEN
        RAISE EXCEPTION 'Purpose is required';
    END IF;

    IF p_period_days IS NULL
       OR p_period_days < 7
       OR p_period_days > 365 THEN
        RAISE EXCEPTION 'Repayment period must be between 7 and 365 days';
    END IF;

    SELECT
        available_limit,
        borrowing_frozen,
        account_status
    INTO
        v_available_limit,
        v_frozen,
        v_status
    FROM public.profiles
    WHERE id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Profile not found';
    END IF;

    IF v_status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'Account is not active';
    END IF;

    IF v_frozen THEN
        RAISE EXCEPTION 'Borrowing is currently frozen';
    END IF;

    IF p_amount > v_available_limit THEN
        RAISE EXCEPTION
            'Requested amount exceeds available borrowing limit';
    END IF;

    INSERT INTO public.loan_requests (
        borrower_id,
        requested_amount,
        funded_amount,
        remaining_amount,
        purpose,
        description,
        status,
        preferred_period_days,
        direct_request_to,
        above_limit_requested
    )
    VALUES (
        v_user_id,
        p_amount,
        0,
        p_amount,
        btrim(p_purpose),
        coalesce(btrim(p_description), ''),
        'REQUESTED',
        p_period_days,
        NULL,
        false
    )
    RETURNING id INTO v_request_id;

    -- Reserve this part of the user's borrowing capacity.
    UPDATE public.profiles
    SET available_limit = available_limit - p_amount
    WHERE id = v_user_id;

    RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.edit_loan_request(p_request_id uuid, p_amount integer, p_purpose text, p_description text, p_period_days integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
    v_request public.loan_requests%rowtype;
begin
    if auth.uid() is null then
        raise exception 'Authentication required';
    end if;

    if p_amount <= 0 then
        raise exception 'Amount must be greater than zero';
    end if;

    if p_period_days <= 0 then
        raise exception 'Repayment period must be greater than zero';
    end if;

    select *
    into v_request
    from public.loan_requests
    where id = p_request_id;

    if not found then
        raise exception 'Loan request not found';
    end if;

    if v_request.borrower_id <> auth.uid() then
        raise exception 'You can only edit your own loan request';
    end if;

    -- Once somebody has contributed, the request cannot be edited.
    if coalesce(v_request.funded_amount, 0) > 0 then
        raise exception 'A funded request cannot be edited';
    end if;

    -- Also protect against an offer existing even if funded_amount
    -- has not yet been synchronised.
    if exists (
        select 1
        from public.loan_offers
        where loan_request_id = p_request_id
    ) then
        raise exception 'A request with an offer cannot be edited';
    end if;

    update public.loan_requests
    set
        requested_amount = p_amount,
        remaining_amount = p_amount,
        purpose = trim(p_purpose),
        description = trim(p_description),
        preferred_period_days = p_period_days
    where id = p_request_id
      and borrower_id = auth.uid();
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_current_profile()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user auth.users%rowtype;
    v_username text;
    v_full_name text;
    v_phone text;
begin

    if auth.uid() is null then
        raise exception 'Not authenticated';
    end if;

    select *
    into v_user
    from auth.users
    where id = auth.uid();

    v_full_name :=
        coalesce(
            nullif(v_user.raw_user_meta_data ->> 'full_name', ''),
            'KashKe User'
        );

    v_username :=
        lower(
            coalesce(
                nullif(v_user.raw_user_meta_data ->> 'username', ''),
                'user_' || substr(v_user.id::text, 1, 8)
            )
        );

    v_phone :=
        coalesce(
            v_user.raw_user_meta_data ->> 'phone',
            ''
        );

    insert into public.profiles (
        id,
        full_name,
        username,
        phone
    )
    values (
        v_user.id,
        v_full_name,
        v_username,
        v_phone
    )
    on conflict (id) do nothing;

    insert into public.wallets (
        user_id,
        balance,
        locked_balance
    )
    values (
        v_user.id,
        0,
        0
    )
    on conflict (user_id) do nothing;

end;
$function$

CREATE OR REPLACE FUNCTION public.preserve_original_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN

    IF TG_OP = 'INSERT' THEN
        NEW.original_due_date := NEW.due_date;
    ELSE
        NEW.original_due_date := OLD.original_due_date;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.public_profile_directory(p_query text DEFAULT ''::text, p_phone_numbers text[] DEFAULT ARRAY[]::text[], p_profile_ids uuid[] DEFAULT ARRAY[]::uuid[])
 RETURNS TABLE(id uuid, full_name text, username text, phone text, bio text, location text, profile_image text, reliability_score integer, reliability_sample_size integer, account_status text, created_at timestamp with time zone, matched_phone text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_query text :=
        lower(
            btrim(
                coalesce(
                    p_query,
                    ''
                )
            )
        );

    v_query_digits text :=
        regexp_replace(
            coalesce(
                p_query,
                ''
            ),
            '[^0-9]',
            '',
            'g'
        );

    v_phone_numbers text[] :=
        coalesce(
            p_phone_numbers,
            array[]::text[]
        );

    v_profile_ids uuid[] :=
        coalesce(
            p_profile_ids,
            array[]::uuid[]
        );

BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in first'
            USING ERRCODE = '28000';
    END IF;


    IF length(
        coalesce(
            p_query,
            ''
        )
    ) > 80
    OR cardinality(v_phone_numbers) > 100
    OR cardinality(v_profile_ids) > 100
    THEN
        RAISE EXCEPTION
            'Directory request is too large';
    END IF;


    RETURN QUERY

    SELECT
        profile.id,
        profile.full_name,
        profile.username,

        ''::text,

        profile.bio,
        profile.location,
        profile.profile_image,

        (
            SELECT score
            FROM public.loan_reliability(
                profile.id
            )
        ),

        (
            SELECT sample_size
            FROM public.loan_reliability(
                profile.id
            )
        ),

        profile.account_status,
        profile.created_at,

        matched.phone


    FROM public.profiles AS profile


    LEFT JOIN LATERAL (

        SELECT
            public.normalize_ke_phone(
                input.phone
            ) AS phone

        FROM unnest(
            v_phone_numbers
        ) AS input(phone)

        WHERE
            public.normalize_ke_phone(
                input.phone
            )
            =
            public.normalize_ke_phone(
                profile.phone
            )

        ORDER BY
            public.normalize_ke_phone(
                input.phone
            )

        LIMIT 1

    ) AS matched
    ON true


    WHERE

        (
            v_query = ''
            AND cardinality(
                v_phone_numbers
            ) = 0
            AND cardinality(
                v_profile_ids
            ) = 0
        )

        OR

        (
            v_query <> ''
            AND (
                strpos(
                    lower(
                        profile.full_name
                    ),
                    v_query
                ) > 0

                OR

                strpos(
                    lower(
                        profile.username
                    ),
                    v_query
                ) > 0

                OR

                (
                    length(
                        v_query_digits
                    ) >= 4

                    AND strpos(
                        public.normalize_ke_phone(
                            profile.phone
                        ),
                        v_query_digits
                    ) > 0
                )
            )
        )

        OR matched.phone IS NOT NULL

        OR profile.id =
            ANY(v_profile_ids)


    ORDER BY
        profile.full_name,
        profile.id;

END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_account_state()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin

    if auth.uid() is null then
        raise exception 'Not authenticated';
    end if;

    perform public.ensure_current_profile();

end;
$function$

CREATE OR REPLACE FUNCTION public.request_loan_offer_terms(p_offer_id uuid, p_interest_rate integer, p_period_days integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_offer public.loan_offers%ROWTYPE;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF p_interest_rate IS NULL OR p_interest_rate < 0 THEN
        RAISE EXCEPTION 'Interest rate cannot be negative';
    END IF;

    IF p_period_days IS NULL
       OR p_period_days < 7
       OR p_period_days > 365 THEN
        RAISE EXCEPTION 'Repayment period must be between 7 and 365 days';
    END IF;

    SELECT *
    INTO v_offer
    FROM public.loan_offers
    WHERE id = p_offer_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Offer not found';
    END IF;

    IF v_offer.borrower_id <> v_user_id THEN
        RAISE EXCEPTION 'Only the borrower can request different terms';
    END IF;

    IF v_offer.status <> 'OFFERED' THEN
        RAISE EXCEPTION 'This offer can no longer be negotiated';
    END IF;

    UPDATE public.loan_offers
    SET
        requested_interest_rate = p_interest_rate,
        requested_repayment_period_days = p_period_days,
        status = 'TERMS_REQUESTED'
    WHERE id = p_offer_id;

    INSERT INTO public.notifications (
        user_id, type, title, message, related_entity_id
    )
    VALUES (
        v_offer.lender_id,
        'LOAN_OFFER_TERMS_REQUESTED',
        'Different terms requested',
        'The borrower requested different terms for your support offer.',
        p_offer_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.send_connection_request(p_recipient_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_requester_id uuid := auth.uid();
    v_connection_id uuid;
    v_existing public.connections%ROWTYPE;
    v_requester_name text;
BEGIN

    IF v_requester_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF p_recipient_id IS NULL THEN
        RAISE EXCEPTION 'Recipient is required';
    END IF;

    IF p_recipient_id = v_requester_id THEN
        RAISE EXCEPTION 'You cannot connect with yourself';
    END IF;


    -- Make sure recipient exists.
    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles
        WHERE id = p_recipient_id
    ) THEN
        RAISE EXCEPTION 'Recipient does not exist';
    END IF;


    -- Get requester's display name for notification.
    SELECT full_name
    INTO v_requester_name
    FROM public.profiles
    WHERE id = v_requester_id;


    -- Check whether these two users already have a connection.
    SELECT *
    INTO v_existing
    FROM public.connections
    WHERE
        (
            requester_id = v_requester_id
            AND recipient_id = p_recipient_id
        )
        OR
        (
            requester_id = p_recipient_id
            AND recipient_id = v_requester_id
        )
    ORDER BY created_at DESC
    LIMIT 1;


    IF FOUND THEN

        IF v_existing.status = 'ACCEPTED' THEN
            RAISE EXCEPTION 'You are already connected';
        END IF;

        IF v_existing.status = 'PENDING' THEN
            RAISE EXCEPTION 'A connection request already exists';
        END IF;


        -- Reuse rejected/removed connection.
        UPDATE public.connections
        SET
            requester_id = v_requester_id,
            recipient_id = p_recipient_id,
            status = 'PENDING',
            accepted_at = NULL,
            responded_at = NULL,
            created_at = now()
        WHERE id = v_existing.id
        RETURNING id INTO v_connection_id;

    ELSE

        INSERT INTO public.connections (
            requester_id,
            recipient_id,
            status
        )
        VALUES (
            v_requester_id,
            p_recipient_id,
            'PENDING'
        )
        RETURNING id INTO v_connection_id;

    END IF;


    -- ========================================================
    -- NOTIFY RECIPIENT
    -- ========================================================

    INSERT INTO public.notifications (
        user_id,
        type,
        title,
        message,
        related_entity_id
    )
    VALUES (
        p_recipient_id,
        'CONNECTION_REQUEST',
        'New connection request',
        coalesce(v_requester_name, 'Someone') ||
            ' sent you a connection request.',
        v_connection_id
    );


    RETURN v_connection_id;

END;
$function$
